inline Mesh loadEmbeddedMesh() {
    Mesh mesh;
    mesh.vertices.assign(std::begin(ship_data::vertices), std::end(ship_data::vertices));
    mesh.indices.assign(std::begin(ship_data::indices), std::end(ship_data::indices));
    return mesh;
}
